// Bubble positions are fractions of the page (0.0-1.0), top-left origin —
// page size varies per exam (see each OmrExamTemplate's pageWidthPt/
// pageHeightPt), matching the printed PDFs in /answer_sheets.
// Regenerate with: cd tool && dart run generate_sheets.dart
//
// OCR crops retain the full field width, including handwriting below captions.
// Printed captions are removed by name_ocr_cleanup.dart after recognition.
//
// EXCEPTION (2026-09-13): AT's lastNameFieldRect/firstNameFieldRect/
// middleInitialFieldRect are clipped 14pt off the top instead — its
// caption sits on its own line above the handwriting rather than inline
// with it (see generate_sheets.dart's clipCaptionTop/atCaptionInsetPt).
// Hand-patched rather than produced by an actual generator run —
// `dart run` still can't complete in this environment (see the
// 2026-09-13 note this replaces, same dartcv4/CMake block); trust a real
// regeneration's output over this if the two ever disagree.

class BubblePos {
  final String choice;
  final double xFrac;
  final double yFrac;
  const BubblePos(this.choice, this.xFrac, this.yFrac);
}

class OmrSection {
  final String name;
  final int itemCount;
  final Map<int, List<BubblePos>> items;
  const OmrSection({required this.name, required this.itemCount, required this.items});
}

class OmrCorner {
  final double xFrac;
  final double yFrac;
  const OmrCorner(this.xFrac, this.yFrac);
}

/// A fractional bounding box (0.0-1.0 of the page, top-left origin — same
/// convention as [BubblePos]/[OmrCorner]). Used only to crop a printed
/// hand-written field (Last Name / First Name) out of a perspective-
/// corrected scan for on-device OCR; never used for bubble scoring.
class OmrFieldRect {
  final double xFrac;
  final double yFrac;
  final double widthFrac;
  final double heightFrac;
  const OmrFieldRect(this.xFrac, this.yFrac, this.widthFrac, this.heightFrac);
}

class OmrExamTemplate {
